"""Offline compare native PDF first-page identity/edition to observed API latest-job banner."""
import argparse,json,re,unicodedata
from pathlib import Path
p=argparse.ArgumentParser();p.add_argument('folder',type=Path);a=p.parse_args();r=json.loads((a.folder/'receipt.json').read_text());ins=json.loads((a.folder/'publisher-pdf-inspection.json').read_text());first=ins['selected_pages'][0]['text'];norm=lambda s:re.sub('[^a-z0-9]','',unicodedata.normalize('NFKD',s).lower());city=r['product']['Client']['ClientName'];state=r['product']['Client']['State']['StateName'];banner=r['job'].get('BannerText') or '';jobname=r['job']['Name'];supp=re.search(r'(?:Supplement|Supp[.]?(?: No[.]?)?)\s*(\d+(?:[.]\d+)?)',jobname,re.I);pdfsupp=re.search(r'(?:Supplement|Supp[.]?)(?:\s*(?:No[.]?|Number))?\s*(\d+(?:[.]\d+)?)',first,re.I);identity=norm(city) in norm(first) and norm(state) in norm(first);update=re.search(r'Update\s*(\d+)',jobname,re.I);pdfupdate=re.search(r'Update\s*(\d+)',first,re.I);edition=bool(supp and pdfsupp and supp.group(1)==pdfsupp.group(1) and (not update or (pdfupdate and update.group(1)==pdfupdate.group(1))));apiord=re.search(r'Ordinances?\s+(?:No[.]?\s*|through\s*)?([0-9]+(?:-[0-9]+)*)',banner,re.I);pdford=re.search(r'Ordinances?\s+(?:No[.]?\s*|through\s*)?([0-9]+(?:-[0-9]+)*)',first,re.I);ordmatch=bool(apiord and pdford and apiord.group(1)==pdford.group(1));method='supplement/update tokens';
if jobname.lower()=='republication':edition='REPUBLICATION' in first.upper().splitlines()[0] and ordmatch;method='republication heading and matching codified-through ordinance number'
if apiord and not ordmatch:edition=False
result={'api_client_name':city,'api_state_name':state,'api_job_name':jobname,'api_job_id':r['job']['Id'],'api_banner':banner,'pdf_identity_match':identity,'pdf_edition_match':edition,'edition_comparison_method':method,'api_codified_ordinance':apiord.group(1) if apiord else None,'pdf_codified_ordinance':pdford.group(1) if pdford else None,'api_update':update.group(1) if update else None,'pdf_update':pdfupdate.group(1) if pdfupdate else None,'api_supplement':supp.group(1) if supp else None,'pdf_supplement':pdfsupp.group(1) if pdfsupp and jobname.lower()!='republication' else None,'scope':'First native PDF page compared to jurisdiction/state and supplement/update tokens or republication heading plus codified ordinance from observed API latest-job; not full-document/current-law completeness. Historical instruction sheets may follow.','pdf_sha256':ins['sha256']};(a.folder/'edition-check.json').write_text(json.dumps(result,indent=2));print(json.dumps(result,indent=2))
